function simulate(input) {
 const s={...common,...input}; let cash=0,debt=0,unlevered=0,payback=null;const rows=[];
 for(let m=0;m<=s.horizon_month;m++){
 const active=m>=s.acceptance_month;
 const draw=m===s.debt_draw_month?s.debt_commitment:0;
 debt+=draw;
 const interest=debt*s.debt_annual_rate/12;
 const repay=s.debt_draw_month!==null&&m>=s.debt_draw_month+s.first_principal_month_offset?Math.min(debt,s.debt_commitment/s.amortization_months):0;
 const capex=(m===0?s.capex_deposit:0)+(m===s.install_payment_month?s.capex_install:0)+(m===s.acceptance_month?s.capex_acceptance:0);
 const equity=m===0?s.equity_m0:0;
 const revenue=active?s.max_monthly_revenue_at_full_utilization*s.price_factor*s.utilization:0;
 const variable=active?s.variable_cash_cost_at_full_utilization*s.utilization:0;
 const fixed=active?s.operating_fixed_cash_cost:s.pre_acceptance_monthly_cash_cost;
 const maintenance=active?s.monthly_maintenance_cash_capex:0;
 const cfads=revenue-variable-fixed-maintenance;
 const projectFCF=cfads-capex;
 unlevered+=projectFCF;
 cash+=equity+draw+projectFCF-interest-repay;
 debt-=repay;
 if(payback===null&&m>=s.acceptance_month&&unlevered>=-1e-9)payback=m;
 rows.push({month:m,equity,draw,revenue,variable_cash_cost:variable,fixed_cash_cost:fixed,maintenance_capex:maintenance,initial_capex_payment:capex,cfads,interest,principal:repay,debt_end:debt,cash_end:cash,cumulative_project_fcf:unlevered});
 }
 const r6=x=>Math.round(x*1e6)/1e6;
 return {id:s.id,label:s.label,inputs:input,output:{cash_m12:r6(rows[12].cash_end),cash_m24:r6(rows[24].cash_end),max_extra_funding_gap_m0_m24:r6(Math.max(0,-Math.min(...rows.slice(0,25).map(r=>r.cash_end)))),min_cash_m0_m24:r6(Math.min(...rows.slice(0,25).map(r=>r.cash_end))),project_simple_payback_month_within72:payback,cumulative_project_fcf_m72:r6(rows[72].cumulative_project_fcf),debt_end_m24:r6(rows[24].debt_end),monthly_cfads_after_acceptance:r6(rows[s.acceptance_month].cfads),monthly_illustrative_ebit_after_acceptance:r6(rows[s.acceptance_month].revenue-rows[s.acceptance_month].variable_cash_cost-s.operating_fixed_cash_cost-s.initial_project_capex/s.accounting_depreciation_months)},monthly_rows:rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k,typeof v==="number"?r6(v):v])))};
}
